import React, { useState, useEffect } from 'react';
import HomeScreen from './components/HomeScreen';
import DialogueMode from './components/DialogueMode';
import ReviewPostcard from './components/ReviewPostcard';
import WorldMapReview from './components/WorldMapReview';
import { testKimiApi } from './testKimiApi';

function App() {
  const [currentScreen, setCurrentScreen] = useState('home'); // home, dialogue, review, map
  const [selectedImage, setSelectedImage] = useState(null);
  const [conversation, setConversation] = useState([]);
  const [selectedPostcard, setSelectedPostcard] = useState(null);

  // Run Kimi API test when app starts
  useEffect(() => {
    testKimiApi();
  }, []);

  const startDialogue = (imageId) => {
    setSelectedImage(imageId);
    setCurrentScreen('dialogue');
  };

  const finishDialogue = (conversationData) => {
    setConversation(conversationData);
    setCurrentScreen('review');
  };

  const practiceAnotherImage = () => {
    // Reset state and go back to home screen
    setSelectedImage(null);
    setConversation([]);
    setSelectedPostcard(null);
    setCurrentScreen('home');
  };

  const openMapReview = () => {
    setCurrentScreen('map');
  };

  const handleReviewPostcard = (postcard) => {
    setSelectedPostcard(postcard);
    setCurrentScreen('review');
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100">
      {currentScreen === 'home' && (
        <HomeScreen 
          onStartDialogue={startDialogue} 
          onOpenMapReview={openMapReview}
        />
      )}

      {currentScreen === 'dialogue' && (
        <DialogueMode 
          imageId={selectedImage} 
          onFinish={finishDialogue}
          onCancel={practiceAnotherImage}
        />
      )}

      {currentScreen === 'review' && (
        <ReviewPostcard 
          imageId={selectedPostcard?.imageId || selectedImage} 
          conversation={selectedPostcard?.conversation || conversation}
          onPracticeAnother={practiceAnotherImage}
          feedback={selectedPostcard?.feedback}
        />
      )}

      {currentScreen === 'map' && (
        <WorldMapReview 
          onBack={practiceAnotherImage}
          onReviewPostcard={handleReviewPostcard}
        />
      )}
    </div>
  );
}

export default App;
